        if (current < in.count()) return Response.status(409).entity(new ApiError("OUT_OF_STOCK", "在庫が足りません")).build();
        stock.put(in.item(), current - in.count());
        return Response.status(201).entity(new OrderDto(1, in.item(), in.count())).build();
    }
}

public class OrderApiWithAuth {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String caller = sc.next();
        if (caller.equals("_")) caller = "";
        String role = sc.next();
        String item = sc.next();
        if (item.equals("_")) item = "";
        CreateOrder in = new CreateOrder(item, sc.nextInt());
